function crackPassword(password) {
  // Generate a random string of characters
  const randomString = generateRandomString(10);

  // Compare the generated string with the password
  if (password === randomString) {
    return true;
  }

  // If the password does not match, try different combinations of characters
  for (let i = 0; i < 10; i++) {
    const char = String.fromCharCode('a'.charCodeAt(0) + i);
    const newString = randomString.replace(new RegExp(char, 'g'), '');
    if (newString !== '') {
      break;
    }
  }

  // If no combination worked, return false
  return false;
}

// Example usage
